//! Provider-dispatch-only CPU/allocation control, excluding browser work.
// Rust guideline compliant 2026-02-21
#[path = "/Users/pierre/.codex/worktrees/af04/gpui-toolkit/crates/gpui-web-foreign/src/dispatch.rs"]
mod dispatch;
use gpui_profiler::AllocSnapshot;
use std::{
    cell::{Cell, RefCell},
    hint::black_box,
    time::Instant,
};
fn cpu_ns() -> u64 {
    let mut time = libc::timespec {
        tv_sec: 0,
        tv_nsec: 0,
    };
    // SAFETY: valid process clock and aligned writable timespec storage.
    assert_eq!(
        unsafe { libc::clock_gettime(libc::CLOCK_PROCESS_CPUTIME_ID, &raw mut time) },
        0
    );
    u64::try_from(time.tv_sec).unwrap() * 1_000_000_000 + u64::try_from(time.tv_nsec).unwrap()
}
fn measure(mut invoke: impl FnMut(u64), read: impl FnOnce() -> u64) {
    const N: u64 = 4_194_304;
    for _ in 0..4096 {
        invoke(black_box(1));
    }
    let before = AllocSnapshot::now();
    let wall = Instant::now();
    let cpu = cpu_ns();
    for _ in 0..N {
        invoke(black_box(1));
    }
    let elapsed = cpu_ns() - cpu;
    let wall_ns = wall.elapsed().as_nanos();
    let alloc = AllocSnapshot::delta_since(before);
    let checksum = read();
    assert_eq!(checksum, N + 4096);
    assert_eq!(alloc.count, 0);
    assert_eq!(alloc.bytes, 0);
    println!(
        "{{\"iterations\":{N},\"cpu_ns\":{elapsed},\"wall_ns\":{wall_ns},\"allocations\":{},\"bytes\":{},\"checksum\":{checksum}}}",
        alloc.count, alloc.bytes
    );
}
fn main() {
    let mode = std::env::args().nth(1).unwrap();
    if mode == "borrowed" {
        let slot = RefCell::new(Some(Box::new(0u64)));
        measure(
            |value| {
                let mut slot = black_box(&slot).borrow_mut();
                let provider = slot.as_mut().unwrap();
                **provider = black_box(**provider).wrapping_add(value);
            },
            || **slot.borrow().as_ref().unwrap(),
        );
    } else {
        let slot = dispatch::SerializedProvider::<Box<u64>, u64>::new(Some(Box::new(0)));
        measure(
            |value| {
                black_box(&slot)
                    .dispatch(value, 0, |provider, value| {
                        **provider = black_box(**provider).wrapping_add(value);
                    })
                    .unwrap();
            },
            || {
                let result = Cell::new(0);
                slot.dispatch(0, 0, |provider, _| result.set(**provider))
                    .unwrap();
                result.get()
            },
        );
        slot.replace(Box::new(0));
        slot.close();
    }
}
